<?php
declare(strict_types=1);
require_once __DIR__.'/api/pos_helpers.php';
$slug=slugify((string)($_GET['tag']??''));
$pdo=db();$st=$pdo->prepare('SELECT id,name,slug FROM product_tags WHERE slug=? LIMIT 1');$st->execute([$slug]);$tag=$st->fetch();
if(!$tag){http_response_code(404);$title='Tag not found | Goodlucks Goods';$description='This product tag could not be found.';$products=[];$tagName='Tag not found';}
else{
  $title=(string)$tag['name'].' Furniture & Home Products | Goodlucks Goods';
  $description='Explore Goodlucks Goods products tagged '.(string)$tag['name'].'. Shop furniture and home products in Ghana with convenient ordering and delivery.';
  $tagName=(string)$tag['name'];$ids=$pdo->prepare("SELECT p.id FROM products p JOIN product_tag_map m ON m.product_id=p.id WHERE m.tag_id=? AND p.product_status='published' ORDER BY COALESCE(p.published_at,p.created_at) DESC,p.id DESC");$ids->execute([(int)$tag['id']]);$products=[];foreach($ids->fetchAll(PDO::FETCH_COLUMN) as $id){$r=product_rows("p.id=? AND p.product_status='published'",[(int)$id]);if($r)$products[]=$r[0];}
  if(!$products){http_response_code(404);}
}
$canonical=pos_origin().'/tag/'.rawurlencode($slug);
function tag_e(mixed $x):string{return htmlspecialchars((string)$x,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
function tag_img(string $x):string{if($x==='' )return '/favicon.png';if(preg_match('#^https?://#i',$x)||str_starts_with($x,'/'))return $x;return '/api/'.ltrim($x,'/');}
header('Content-Type: text/html; charset=utf-8');header('X-Content-Type-Options: nosniff');
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=tag_e($title)?></title><meta name="description" content="<?=tag_e($description)?>"><link rel="canonical" href="<?=tag_e($canonical)?>"><meta property="og:site_name" content="Goodlucks Goods"><meta property="og:title" content="<?=tag_e($title)?>"><meta property="og:description" content="<?=tag_e($description)?>"><meta property="og:url" content="<?=tag_e($canonical)?>"><meta property="og:type" content="website"><meta property="og:image" content="https://shop.goodlucks.co/goodlucks-social-preview.png"><meta name="theme-color" content="#252A34"><link rel="icon" href="/favicon.svg" type="image/svg+xml"><style>
