</style></head><body><header class="head"><a href="/"><img class="logo" src="/goodlucks-goods-logo.svg" alt="Goodlucks Goods"></a><a href="/categories">Browse all categories →</a></header><main class="wrap"><div class="crumb"><a href="/">Home</a> / Product tag</div><section class="intro"><h1><?=tag_e($tagName)?></h1><p><?=tag_e($description)?></p></section><?php if($products): ?><div class="grid"><?php foreach($products as $product): ?><a class="card" href="/product/<?=rawurlencode((string)$product['slug'])?>"><img src="<?=tag_e(tag_img((string)($product['featuredImage']??'')))?>" alt="<?=tag_e($product['name'])?>" loading="lazy"><div class="body"><h2><?=tag_e($product['name'])?></h2><div class="price">GH₵ <?=number_format((float)($product['discountPrice']??$product['price']),2,'.',',')?></div><span class="view">View product →</span></div></a><?php endforeach; ?></div><?php else: ?><div class="empty"><h2>No published products found</h2><p>This tag does not currently have published products.</p><a href="/categories">Browse all categories</a></div><?php endif; ?></main><footer class="footer">Goodlucks Goods · Your destination for style</footer></body></html>
